      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "In mice, the methoxy-substituted aromatic compound HI-236 reached brain concentrations comparable to plasma, directly showing that this structural class can easily cross the blood-brain barrier.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Ex vivo rat studies with [11C]JNJ-16567083, a methoxy-substituted aromatic/heteroaromatic compound, showed good brain uptake, further supporting CNS access for this general scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Pyridoxal, a small polar heteroaromatic molecule, increased in human CSF after supplementation, demonstrating that even polar heteroaromatic compounds can achieve meaningful blood-brain barrier crossing.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
